changes.diff:
--- a/infra/bootstrap/providers.tf
+++ b/infra/bootstrap/providers.tf
@@ -1,3 +1,17 @@
+terraform {
+  required_version = ">= 1.11"
+
+  required_providers {
+    aws = {
+      source  = "hashicorp/aws"
+      version = "6.73.0"
+    }
+  }
+  # Sem backend remoto de propósito: esta raiz cria o bucket que guarda o state das demais.
+}
+
 provider "aws" {
-  region = "sa-east-1"
+  region              = var.aws_region
+  profile             = var.aws_profile
+  allowed_account_ids = ["123456789012"]
 }

--- /dev/null
+++ b/infra/bootstrap/resource.tf
@@ -1,0 +1,43 @@
+# ------------------------- State Bucket -----------------------------
+resource "aws_s3_bucket" "tf_state" {
+  bucket = var.bucket_state
+
+  tags = {
+    Project     = "loja"
+    Environment = "shared"
+    ManagedBy   = "terraform"
+  }
+
+  lifecycle {
+    # Apagar este bucket apaga o state de todos os ambientes.
+    prevent_destroy = true
+  }
+}
+
+# Mantém versões anteriores do state para recuperar de uma escrita errada.
+resource "aws_s3_bucket_versioning" "tf_state" {
+  bucket = aws_s3_bucket.tf_state.id
+
+  versioning_configuration {
+    status = "Enabled"
+  }
+}
+
+resource "aws_s3_bucket_server_side_encryption_configuration" "tf_state" {
+  bucket = aws_s3_bucket.tf_state.id
+
+  rule {
+    apply_server_side_encryption_by_default {
+      sse_algorithm = "AES256"
+    }
+  }
+}
+
+resource "aws_s3_bucket_public_access_block" "tf_state" {
+  bucket = aws_s3_bucket.tf_state.id
+
+  block_public_acls       = true
+  block_public_policy     = true
+  ignore_public_acls      = true
+  restrict_public_buckets = true
+}
